// Scheduled runs use the BLOG_TOPIC_BRIEF environment variable. For a one-off run from the Manual Trigger, type a brief below.
// The brief must be a short description of a public topic. Never paste participant, enquiry or staff details here.
const MANUAL_BRIEF = '';
const brief = String(MANUAL_BRIEF || $env.BLOG_TOPIC_BRIEF || '').replace(/\s+/g, ' ').trim();
return [{ json: { brief, briefProvided: brief.length >= 20 && brief.length <= 300 } }];

// Cheap screen of the brief against titles already in the public search index.
// This is NOT the quality gate. CI runs the real shared-phrasing check (assessDraft in packages/schemas/src/blog.ts) on the draft file.
const STOP = new Set('a an and are as at be but by for from has have he her his how i if in into is it its more not of on or our she so than that the their them then there these they this to was we were what when which who will with you your can may also about all any been being do does each other some such these those up out new one two'.split(' '));
const SIMILAR_OVERLAP = 0.7;
const MIN_SHARED_TERMS = 3;
const terms = (text) => new Set(String(text).toLowerCase().replace(/[^a-z0-9\s'-]/g, ' ').split(/\s+/).filter((w) => w.length > 2 && !STOP.has(w)));
const overlap = (a, b) => {
  if (!a.size || !b.size) return { shared: 0, ratio: 0 };
  let shared = 0;
  for (const t of a) if (b.has(t)) shared++;
  return { shared, ratio: shared / Math.min(a.size, b.size) };
};
// Mirrors checkPromptSafety() in packages/automation/src/content.ts: nothing that looks personal may reach the model.
const promptProblems = (text) => {
  const problems = [];
  if (/[^\s@]+@[^\s@]+\.[^\s@]+/.test(text)) problems.push('contains_email');
  if (/(?:\+?61|0)[\s-]?[2-478](?:[\s-]?\d){8}/.test(text)) problems.push('contains_phone');
  if (/(?<!\d)(?:\d[\s-]?){8}\d(?!\d)/.test(text)) problems.push('contains_ndis_number_like');
  return problems;
};

const { brief, briefProvided } = $('Topic brief').first().json;
const api = $input.first().json || {};
const rows = api.apiVersion === '1' && Array.isArray(api.data) ? api.data : null;

let reason = '';
const similarTo = [];
const existingTitles = [];
const existingSlugs = [];

if (!briefProvided) {
  reason = 'brief_missing_or_wrong_length';
} else if (!rows) {
  reason = 'search_index_unreadable_or_unexpected_version';
} else {
  for (const r of rows) {
    if (r && typeof r.title === 'string') existingTitles.push(r.title);
    if (r && typeof r.id === 'string') existingSlugs.push(r.id);
  }
  const briefTerms = terms(brief);
  for (const r of rows) {
    if (!r || typeof r.title !== 'string') continue;
    const o = overlap(briefTerms, terms(r.title));
    if (o.shared >= MIN_SHARED_TERMS && o.ratio >= SIMILAR_OVERLAP) similarTo.push({ id: r.id, title: r.title });
  }
  const problems = promptProblems(brief + '\n' + existingTitles.join('\n'));
  if (similarTo.length) reason = 'similar_content_exists';
  else if (problems.length) reason = 'prompt_safety:' + problems.join(',');
}

const proceed = reason === '';
return [{
  json: {
    proceed,
    reason,
    brief,
    similarTo: similarTo.slice(0, 5),
    existingTitles: existingTitles.slice(0, 300),
    existingSlugs: existingSlugs.slice(0, 300),
    notifySubject: 'Blog draft workflow: nothing was opened (' + (reason || 'ok') + ')',
    notifyText: [
      'The weekly blog draft workflow stopped before drafting. No branch, file or pull request was created.',
      'Reason: ' + reason,
      similarTo.length ? 'Similar existing content: ' + similarTo.slice(0, 5).map((s) => s.title).join(' | ') : '',
      'Nothing was published and nothing was sent to a language model.',
    ].filter(Boolean).join('\n'),
  },
}];

// Rules below restate packages/schemas/src/blog.ts (blogDraftSchema, assessDraft, AUTHORITATIVE_DOMAINS) and the banned wording in banned.ts.
// If those change, change this node too; tests/n8n-exports.test.ts compares the lists that are exported.
const CATEGORIES = ['for-coordinators', 'housing', 'funding-explained', 'working-with-us', 'regional', 'news'];
const REGIONS = ['central-coast', 'newcastle', 'dubbo', 'orange', 'tamworth', 'gunnedah'];
const SERVICES = ['core-support', 'supported-independent-living', 'sda', 'short-term-accommodation', 'support-coordinator', 'community-access'];
const AUTHORITATIVE_DOMAINS = ['ndis.gov.au', 'ndiscommission.gov.au', 'dss.gov.au', 'health.gov.au', 'aihw.gov.au', 'legislation.gov.au', 'accc.gov.au', 'oaic.gov.au', 'servicesaustralia.gov.au', 'abs.gov.au', 'nsw.gov.au', 'ombo.nsw.gov.au', 'nds.org.au', 'pwd.org.au', 'stylemanual.gov.au'];

if (!$env.LLM_MODEL) throw new Error('LLM_MODEL is not set');
const dup = $('Duplicate title check').first().json;

const system = [
  'You write first drafts of plain-English articles for the website of a registered NDIS provider in regional New South Wales, Australia.',
  'A named human reviewer will fact-check, rewrite and approve your draft before anything is published. Your draft is a starting point only.',
  '',
  'Rules you must follow:',
  '1. Reply with one JSON object and nothing else. No markdown fences and no commentary.',
  '2. Never include personal information about any participant, family member, worker or enquirer. Do not invent people, quotes, testimonials, case studies or statistics.',
  '3. Only state facts you are sure of. If you are unsure, leave the claim out. Do not state prices, response times, registration numbers, addresses, vacancies or availability.',
  '4. Do not use the provider\'s brand name. Write to the reader as "you".',
  '5. Banned wording: "NDIS approved", "approved NDIS provider", "NDIS endorsed", "fully covered by the NDIS", "best provider", "leading NDIS", "most trusted", "the obvious choice", guarantees or promises, "refer a friend", rewards or vouchers, certainty about eligibility ("you will definitely get"), outcome promises, and medical-style claims ("cure", "miracle", "breakthrough").',
  '6. Plain English at about school grade 8 to 10. Short sentences. Australian spelling. No keyword stuffing: no single term above 3 percent of the words.',
  '7. Sources: give 2 to 12 sources. At least 2 must be pages on these official domains: ' + AUTHORITATIVE_DOMAINS.join(', ') + '. Use the real page title as the label and a real https URL. Never guess a URL. If you are not sure a specific page exists, use the home page of that organisation.',
  '8. Do not output author, aiAssisted, aiNotes or publishedAt. The workflow adds them.',
].join('\n');

const schema = [
  '{',
  '  "slug": "lowercase words joined by hyphens, at most 80 characters",',
  '  "kind": "post",',
  '  "title": "20 to 70 characters",',
  '  "summary": "80 to 170 characters",',
  '  "answer": "180 to 560 characters (about 40 to 90 words). Answer the reader\'s question first, in one paragraph that ends as a full sentence.",',
  '  "category": "one of: ' + CATEGORIES.join(', ') + '",',
  '  "tags": ["up to 6 slugs"],',
  '  "regions": ["zero or more of: ' + REGIONS.join(', ') + '"],',
  '  "services": ["zero or more of: ' + SERVICES.join(', ') + '"],',
  '  "sections": [ { "heading": "8 to 90 characters, unique", "body": ["1 to 8 paragraphs, each 40 to 1400 characters"] } ],',
  '  "faqs": [ { "q": "10 to 160 characters", "a": "40 to 700 characters" } ],',
  '  "sources": [ { "label": "5 to 140 characters", "url": "an https URL" } ]',
  '}',
  'Use 3 to 12 sections and at most 8 faqs. A post needs at least 600 words in total (title, summary, answer, sections and faqs).',
].join('\n');

const user = [
  'Write one draft that matches the JSON shape below.',
  '',
  'Brief: ' + dup.brief,
  '',
  'Existing titles on the site. Do not repeat or closely paraphrase them:',
  ...dup.existingTitles.slice(0, 150).map((t) => '- ' + t),
  '',
  'JSON shape:',
  schema,
].join('\n');

// Mirrors checkPromptSafety() in packages/automation/src/content.ts. Fail closed: stop the workflow rather than send anything personal.
const prompt = system + '\n' + user;
const problems = [];
if (/[^\s@]+@[^\s@]+\.[^\s@]+/.test(prompt)) problems.push('contains_email');
if (/(?:\+?61|0)[\s-]?[2-478](?:[\s-]?\d){8}/.test(prompt)) problems.push('contains_phone');
if (/(?<!\d)(?:\d[\s-]?){8}\d(?!\d)/.test(prompt)) problems.push('contains_ndis_number_like');
if (problems.length) throw new Error('Prompt safety check failed: ' + problems.join(', '));

// Messages-style request body. The exact shape depends on the LLM provider that is chosen: adapt this object and the
// response extraction in the "Pre-checks" node together. Not tested against any provider.
return [{ json: { requestBody: { model: $env.LLM_MODEL, max_tokens: 4096, system, messages: [{ role: 'user', content: user }] }, promptChars: prompt.length } }];

// Cheap checks only. They mirror blogDraftSchema and assessDraft in packages/schemas/src/blog.ts so obviously bad drafts never reach a PR.
// The real gates still run in CI (content-gates workflow: content:ingest --dry-run and content:verify) and a named human reviews.
const CATEGORIES = ['for-coordinators', 'housing', 'funding-explained', 'working-with-us', 'regional', 'news'];
const REGIONS = ['central-coast', 'newcastle', 'dubbo', 'orange', 'tamworth', 'gunnedah'];
const SERVICES = ['core-support', 'supported-independent-living', 'sda', 'short-term-accommodation', 'support-coordinator', 'community-access'];
const AUTHORITATIVE_DOMAINS = ['ndis.gov.au', 'ndiscommission.gov.au', 'dss.gov.au', 'health.gov.au', 'aihw.gov.au', 'legislation.gov.au', 'accc.gov.au', 'oaic.gov.au', 'servicesaustralia.gov.au', 'abs.gov.au', 'nsw.gov.au', 'ombo.nsw.gov.au', 'nds.org.au', 'pwd.org.au', 'stylemanual.gov.au'];
const SLUG = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const MIN_WORDS = { post: 600, guide: 450 };
const SIMILAR_OVERLAP = 0.7;
const MIN_SHARED_TERMS = 3;
const STOP = new Set('a an and are as at be but by for from has have he her his how i if in into is it its more not of on or our she so than that the their them then there these they this to was we were what when which who will with you your can may also about all any been being do does each other some such these those up out new one two'.split(' '));
const SENSITIVE_TOPICS = [
  [/\beligib(le|ility)\b/i, 'eligibility'],
  [/\bfund(ing|ed|s)?\b/i, 'funding'],
  [/\b(plan budget|plan review|access request|reasonable and necessary|price limits?|pricing arrangements?)\b/i, 'plan_rules'],
];

const tokens = (t) => String(t).toLowerCase().replace(/[^a-z0-9\s'-]/g, ' ').split(/\s+/).filter(Boolean);
const terms = (t) => new Set(tokens(t).filter((w) => w.length > 2 && !STOP.has(w)));
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const strList = (v) => (Array.isArray(v) ? v.filter((x) => typeof x === 'string').map((x) => x.trim()) : []);
const inRange = (s, min, max) => typeof s === 'string' && s.length >= min && s.length <= max;

const dup = $('Duplicate title check').first().json;
const errors = [];
const warnings = [];

// 1. Pull the model's text out of the response. Handles a Messages-style response (content blocks) and a chat-completions-style response.
const r = $input.first().json || {};
let text = '';
if (Array.isArray(r.content)) text = r.content.filter((b) => b && b.type === 'text' && typeof b.text === 'string').map((b) => b.text).join('');
else if (Array.isArray(r.choices) && r.choices[0] && r.choices[0].message && typeof r.choices[0].message.content === 'string') text = r.choices[0].message.content;
else if (typeof r.text === 'string') text = r.text;

let p = null;
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start >= 0 && end > start) {
  try { p = JSON.parse(text.slice(start, end + 1)); } catch (e) { p = null; }
}
if (!p || typeof p !== 'object' || Array.isArray(p)) {
  errors.push('model_output_is_not_a_json_object');
  p = {};
}

// 2. Build the draft from known fields only. Anything else the model added is dropped. Author is a human or named role from the environment.
const author = String($env.BLOG_AUTHOR_NAME || '').trim();
const draft = {
  slug: str(p.slug),
  kind: p.kind === 'guide' ? 'guide' : 'post',
  title: str(p.title),
  summary: str(p.summary),
  answer: str(p.answer),
  category: p.category,
  tags: strList(p.tags),
  regions: strList(p.regions),
  services: strList(p.services),
  sections: Array.isArray(p.sections) ? p.sections.map((s) => ({ heading: str(s && s.heading), body: strList(s && s.body) })) : [],
  faqs: Array.isArray(p.faqs) ? p.faqs.map((f) => ({ q: str(f && f.q), a: str(f && f.a) })) : [],
  sources: Array.isArray(p.sources) ? p.sources.map((s) => ({ label: str(s && s.label), url: str(s && s.url) })) : [],
  author,
  aiAssisted: true,
  aiNotes: 'First draft written by a language model from a one-line brief. Every fact and source needs a human check, and the text needs a human edit, before approval.',
};

// 3. Required fields and lengths (blogDraftSchema)
if (!SLUG.test(draft.slug) || draft.slug.length > 80) errors.push('slug_invalid');
if (dup.existingSlugs.includes(draft.slug)) errors.push('slug_already_exists');
if (!inRange(draft.title, 20, 70)) errors.push('title_length_20_to_70');
if (!inRange(draft.summary, 80, 170)) errors.push('summary_length_80_to_170');
if (!inRange(draft.answer, 180, 560)) errors.push('answer_length_180_to_560');
if (!CATEGORIES.includes(draft.category)) errors.push('category_invalid');
if (draft.tags.length > 6 || draft.tags.some((t) => !SLUG.test(t) || t.length > 80)) errors.push('tags_invalid');
if (draft.regions.length > 6 || draft.regions.some((x) => !REGIONS.includes(x))) errors.push('regions_invalid');
if (draft.services.length > 6 || draft.services.some((x) => !SERVICES.includes(x))) errors.push('services_invalid');
if (draft.sections.length < 3 || draft.sections.length > 12) errors.push('sections_need_3_to_12');
for (const s of draft.sections) {
  if (!inRange(s.heading, 8, 90)) errors.push('section_heading_length_8_to_90');
  if (s.body.length < 1 || s.body.length > 8 || s.body.some((b) => !inRange(b, 40, 1400))) errors.push('section_body_1_to_8_paragraphs_of_40_to_1400_characters');
}
if (draft.faqs.length > 8 || draft.faqs.some((f) => !inRange(f.q, 10, 160) || !inRange(f.a, 40, 700))) errors.push('faqs_invalid');
if (draft.sources.length < 2 || draft.sources.length > 12) errors.push('sources_need_2_to_12');
if (!inRange(draft.author, 3, 80)) errors.push('author_not_configured');
if (/\bai\b|artificial intelligence|chatgpt|claude|gpt/i.test(draft.author)) errors.push('author_must_be_a_human_or_named_role');
if (new Set(draft.sections.map((s) => s.heading.toLowerCase())).size !== draft.sections.length) errors.push('duplicate_section_headings');

// 4. Sources: https, and at least two on the authoritative allow-list (assessDraft)
let authoritative = 0;
for (const s of draft.sources) {
  if (!inRange(s.label, 5, 140)) errors.push('source_label_length_5_to_140');
  try {
    const u = new URL(s.url);
    if (u.protocol !== 'https:') { errors.push('source_url_not_https'); continue; }
    const host = u.hostname.replace(/^www\./, '');
    if (AUTHORITATIVE_DOMAINS.some((d) => host === d || host.endsWith('.' + d))) authoritative++;
  } catch (e) {
    errors.push('source_url_invalid');
  }
}
if (authoritative < 2) errors.push('needs_2_authoritative_sources_found_' + authoritative);

// 5. Thin content, using the same word counting as assessDraft
const fullText = [draft.title, draft.summary, draft.answer, ...draft.sections.flatMap((s) => [s.heading, ...s.body]), ...draft.faqs.flatMap((f) => [f.q, f.a])].join('\n');
const words = tokens(fullText).length;
const minWords = MIN_WORDS[draft.kind];
if (words < minWords) errors.push('too_thin_' + words + '_words_minimum_' + minWords);

// 6. Duplicate title against the public search index (cheap screen; CI does the real similarity check)
const normalise = (t) => tokens(t).join(' ');
const titleTerms = terms(draft.title);
for (const existing of dup.existingTitles) {
  if (normalise(existing) === normalise(draft.title)) { errors.push('title_already_exists'); break; }
  const et = terms(existing);
  let shared = 0;
  for (const t of titleTerms) if (et.has(t)) shared++;
  if (titleTerms.size && et.size && shared >= MIN_SHARED_TERMS && shared / Math.min(titleTerms.size, et.size) >= SIMILAR_OVERLAP) { errors.push('title_very_similar_to_existing'); break; }
}

// 7. Nothing that looks like personal data (same patterns as checkPromptSafety in packages/automation/src/content.ts)
if (/[^\s@]+@[^\s@]+\.[^\s@]+/.test(fullText)) errors.push('possible_personal_data_email');
if (/(?:\+?61|0)[\s-]?[2-478](?:[\s-]?\d){8}/.test(fullText)) errors.push('possible_personal_data_phone');
if (/(?<!\d)(?:\d[\s-]?){8}\d(?!\d)/.test(fullText)) errors.push('possible_personal_data_ndis_number_like');

// 8. Sensitive topics are not blocked, but they are flagged so the PR asks for an NDIS-experienced reviewer (detectSensitiveTopics in content.ts)
const sensitive = SENSITIVE_TOPICS.filter(([re]) => re.test(fullText)).map(([, label]) => label);
if (sensitive.length) warnings.push('sensitive_topics_' + sensitive.join('_'));

const ok = errors.length === 0;
const prBody = [
  '## Automated first draft: not approved, not published',
  '',
  'This pull request was opened by an n8n workflow. A language model wrote the text from a one-line brief. Nothing here is approved. Merging does not publish it: production shows content only when a named reviewer on the reviewer list has approved the exact content (hash lock).',
  '',
  '- Brief: ' + dup.brief,
  '- Kind: ' + draft.kind + ' | Category: ' + draft.category + ' | Words: ' + words,
  sensitive.length ? '- Sensitive topics detected: ' + sensitive.join(', ') + '. An NDIS-experienced reviewer must check this draft.' : '',
  warnings.length ? '- Pre-check warnings: ' + warnings.join(', ') : '',
  '',
  '### Sources proposed by the model (not fetched or checked by the workflow)',
  ...draft.sources.map((s) => '- ' + s.label + ': ' + s.url),
  '',
  '### Reviewer checklist',
  '- [ ] Open every source and check each claim against it. Remove anything that cannot be checked.',
  '- [ ] No participant data, no unverified claims, no banned or promotional wording.',
  '- [ ] Plain English, correct for NSW, nothing implies eligibility or funding certainty.',
  '- [ ] CI content gates are green.',
  '- [ ] Approval is recorded by a named reviewer with the content:approve command.',
].filter((l, i, a) => l !== '' || a[i - 1] !== '').join('\n');

return [{
  json: {
    ok,
    errors,
    warnings,
    slug: draft.slug,
    branch: 'draft/' + draft.slug,
    filePath: 'apps/web/content-drafts/' + draft.slug + '.json',
    fileContent: ok ? JSON.stringify(draft, null, 2) + '\n' : '',
    commitMessage: 'Add draft: ' + draft.title,
    prTitle: 'Draft: ' + draft.title,
    prBody,
    wordCount: words,
    notifySubject: 'Blog draft workflow: the draft was rejected by pre-checks',
    notifyText: [
      'The weekly blog draft workflow produced a draft that failed the pre-checks. No branch, file or pull request was created.',
      'Problems: ' + errors.join(', '),
      'Nothing was published.',
    ].join('\n'),
  },
}];
